import { AsyncPipe } from '@angular/common';
import { Component, inject, Input } from '@angular/core';
import { map } from 'rxjs';
import { AvatarComponent } from 'src/app/profile/avatar/avatar.component';
import { ProfileService } from 'src/app/profile/profile.service';
import { MenuService } from './menu.service';

@Component({
    selector: 'app-menu-toggle',
    templateUrl: './menu-toggle.component.html',
    styleUrls: ['./menu-toggle.component.scss'],
    imports: [AvatarComponent, AsyncPipe]
})
export class MenuToggleComponent {
  @Input() hideAvatarOnClose = true;

  avatarUrl$ = inject(ProfileService).profile$.pipe(
    map((profile) => profile?.avatar_url)
  );
  menuOpen$ = inject(MenuService).open$;
}
